function summary=validate_hcp_stage3_regularized(workspace)
%VALIDATE_HCP_STAGE3_REGULARIZED 旧时序与已准备模式只读，RSA补合成入口。
if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function;out=fullfile(workspace,'derivatives','function_stage3_regularized_20261017');if isfolder(out),error('cog:Exists','Preserve successful results');end;mkdir(out);subjects=["100206";"100307";"100408"];manifest=table;
for k=1:3,file=fullfile(workspace,'derivatives','function_stage3_rest_extended_20261017_02',subjects(k)+"_roi.mat");manifest=[manifest;table(subjects(k),"","REST1_LR_prefix256",string(file),'VariableNames',{'subject','session','run','data_file'})];end %#ok<AGROW>
c=regularized_fc_config;c.manifestFile=fullfile(out,'runs.tsv');writetable(manifest,c.manifestFile,'FileType','text','Delimiter','\t');c.outputRoot=fullfile(out,'oas');c.execute=true;summary.oas=run_regularized_fc(c);
s=load(fullfile(workspace,'derivatives','function_stage3_generalization_20261017','cross_subject_100307.mat'));data=struct('X',[s.train.X;s.test.X],'Y',[s.train.Y;s.test.Y],'featureIds',s.train.featureIds,'sampleIds',[s.train.sampleIds;s.test.sampleIds],'cvGroups',[s.train.independentUnitIds;s.test.independentUnitIds]);file=fullfile(out,'linear_input.mat');save(file,'data');c=linear_decode_config;c.dataFile=file;c.execute=true;c.options.dependencyNote='Existing TYPEB common-grid patterns; leave one of two subjects out. Shared within-subject HRF and only two participants/family independence not established; engineering prediction only.';
for method={'svm','logistic'},c.options.estimator=method{1};c.outputRoot=fullfile(out,method{1});r=run_linear_decode(c);summary.(method{1})=struct('accuracy',r.accuracy,'nSamples',numel(r.sampleIds));end
% 真实只有story/math两个条件 -> 单个RDM条目，相关天花板无法定义；不用伪造条件。
rng(191);patterns=randn(5,10);base=squareform(pdist(patterns));rdms=zeros(5,5,6);for k=1:6,rdms(:,:,k)=squareform(pdist(patterns+.5*randn(5,10)));end;data=struct('rdms',rdms,'subjectIds',"synthetic_"+string((1:6)'),'conditionIds',"condition_"+string((1:5)'),'modelRDMs',base,'modelNames',"generating_pattern_distance");file=fullfile(out,'SYNTHETIC_rsa_input.mat');save(file,'data');c=rsa_ceiling_config;c.dataFile=file;c.outputRoot=fullfile(out,'SYNTHETIC_rsa_ceiling');c.execute=true;c.options.nBootstrap=99;c.options.designNote='Synthetic six independent subjects; five fixed conditions and generating Euclidean model, no empirical inference.';r=run_rsa_ceiling(c);summary.syntheticRsa=struct('lower',r.lower,'upper',r.upper,'modelMean',r.modelMeanScores);
summary.skipped='Real RSA ceiling/subject bootstrap correlation: prepared TYPEB has only two conditions, hence one distance and zero distance-vector variance. Five-condition/six-subject synthetic complete entrypoint used instead; no invented real labels.';summary.scope='OAS covariance/precision/regularized partial on three existing REST256/6ROI; fixed-lambda native SVM/logistic leave-subject prediction on existing 50 TYPEB units; synthetic fixed-condition Pearson ceiling/model unit-bootstrap. No scientific highdim/behavior inference.';cog.write_json(fullfile(out,'VALIDATION.json'),summary);
end
